`NotificationChannel` uses `ABC` for the abstract contract and `__init_subclass__` as a creation-time hook. Because the hook runs when each subclass is defined, importing the module is enough to fill the registry. The optional keyword keeps helper subclasses out of the registry.

**`notification.py`**

```python
from abc import ABC, abstractmethod

class NotificationChannel(ABC):
    registry = {}

    def __init_subclass__(cls, channel_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if channel_name is not None:
            cls.registry[channel_name] = cls

    @abstractmethod
    def send(self, user, message):
        pass

    @abstractmethod
    def get_status(self, message_id):
        pass


class SMSChannel(NotificationChannel, channel_name="sms"):
    def send(self, user, message):
        print(f"Sending SMS to {user}: {message}")

    def get_status(self, message_id):
        return "DELIVERED"


class EmailChannel(NotificationChannel, channel_name="email"):
    def send(self, user, message):
        print(f"Sending Email to {user}: {message}")

    def get_status(self, message_id):
        return "DELIVERED"


class PushChannel(NotificationChannel, channel_name="push"):
    def send(self, user, message):
        print(f"Sending Push notification to {user}: {message}")

    def get_status(self, message_id):
        return "DELIVERED"
```

**`main.py`**

```python
from notification import NotificationChannel

def main():
    sms = NotificationChannel.registry["sms"]()
    sms.send("Alice", "Your cab has arrived.")

    email = NotificationChannel.registry["email"]()
    email.send("Bob", "Trip receipt")

    push = NotificationChannel.registry["push"]()
    push.send("Charlie", "Driver is nearby")


if __name__ == "__main__":
    main()
```

