The runtime protocol check is deliberately kept out of the logic: `conformance_errors` walks the functions declared on the Protocol, uses `inspect.getattr_static` for presence, and compares positional parameter names after normalising `self`. The registry validates at decoration time, so bad plug-ins fail at import with an actionable message instead of at first use.

**`providers.py`**

```python
import inspect
from typing import Callable, Protocol, TypeVar, runtime_checkable


@runtime_checkable
class ETAProvider(Protocol):
    def estimate_minutes(self, origin: str, destination: str) -> float: ...


def _param_names(fn: Callable[..., object], *, skip_self: bool) -> list[str]:
    params = list(inspect.signature(fn).parameters.values())
    if skip_self and params and params[0].name == "self":
        params = params[1:]
    return [p.name for p in params]


def conformance_errors(candidate: object, protocol: type) -> list[str]:
    """Return human-readable reasons why `candidate` does not satisfy `protocol`.

    Checks method presence and positional parameter names, which
    isinstance() on a runtime_checkable protocol does not.
    """
    errors: list[str] = []
    for name, proto_fn in vars(protocol).items():
        if not inspect.isfunction(proto_fn) or name.startswith("__"):
            continue
        if inspect.getattr_static(candidate, name, None) is None:
            errors.append(f"missing method: {name}")
            continue
        impl = getattr(candidate, name)
        if not callable(impl):
            errors.append(f"not callable: {name}")
            continue
        expected = _param_names(proto_fn, skip_self=True)
        actual = _param_names(impl, skip_self=isinstance(candidate, type))
        if expected != actual:
            errors.append(f"signature mismatch: {name}{tuple(expected)} != {tuple(actual)}")
    return errors


T = TypeVar("T")


class ProviderRegistry:
    def __init__(self, protocol: type) -> None:
        self._protocol = protocol
        self._providers: dict[str, type] = {}

    def register(self, name: str) -> Callable[[type[T]], type[T]]:
        def decorator(cls: type[T]) -> type[T]:
            if name in self._providers:
                raise ValueError(f"provider {name!r} already registered")
            errors = conformance_errors(cls, self._protocol)
            if errors:
                raise TypeError(f"{cls.__name__} does not satisfy {self._protocol.__name__}: " + "; ".join(errors))
            self._providers[name] = cls
            return cls

        return decorator

    def create(self, name: str, /, *args: object, **kwargs: object) -> object:
        try:
            cls = self._providers[name]
        except KeyError:
            raise KeyError(f"unknown provider {name!r}; known: {sorted(self._providers)}") from None
        return cls(*args, **kwargs)

    def names(self) -> list[str]:
        return sorted(self._providers)
```

**`test_providers.py`**

```python
import pytest
from providers import ETAProvider, ProviderRegistry, conformance_errors


class Good:
    def estimate_minutes(self, origin, destination):
        return 12.0


class WrongArity:
    def estimate_minutes(self):
        return 1.0


class WrongNames:
    def estimate_minutes(self, a, b):
        return 1.0


class Missing:
    pass


class NotCallable:
    estimate_minutes = 5


def test_good_candidate_has_no_errors():
    assert conformance_errors(Good, ETAProvider) == []
    assert conformance_errors(Good(), ETAProvider) == []


def test_isinstance_is_fooled_but_conformance_is_not():
    assert isinstance(WrongArity(), ETAProvider)          # names only
    assert conformance_errors(WrongArity(), ETAProvider)  # signature checked


def test_wrong_parameter_names_reported():
    (err,) = conformance_errors(WrongNames, ETAProvider)
    assert err.startswith("signature mismatch: estimate_minutes")


def test_missing_and_not_callable():
    assert conformance_errors(Missing, ETAProvider) == ["missing method: estimate_minutes"]
    assert conformance_errors(NotCallable, ETAProvider) == ["not callable: estimate_minutes"]


def test_registry_registers_and_creates():
    reg = ProviderRegistry(ETAProvider)
    reg.register("good")(Good)
    assert isinstance(reg.create("good"), Good)
    assert reg.names() == ["good"]


def test_registry_rejects_bad_provider_with_reasons():
    reg = ProviderRegistry(ETAProvider)
    with pytest.raises(TypeError, match="signature mismatch"):
        reg.register("bad")(WrongArity)
    assert reg.names() == []


def test_registry_rejects_duplicates():
    reg = ProviderRegistry(ETAProvider)
    reg.register("a")(Good)
    with pytest.raises(ValueError):
        reg.register("a")(Good)


def test_unknown_provider_lists_known_names():
    reg = ProviderRegistry(ETAProvider)
    reg.register("a")(Good)
    with pytest.raises(KeyError, match="known"):
        reg.create("zzz")
```

Run the tests with `pytest -q`.
